'use strict';
const matchRoles=Object.keys(roleSymbols);
const preferenceKey='whose-side-preferences-v1';
let priorities=[null,null];try{const stored=JSON.parse(localStorage.getItem(preferenceKey)||'null');if(Array.isArray(stored)&&stored.length===2)priorities=stored.map(v=>Number.isInteger(v)&&v>=0&&v<matchRoles.length?v:null);}catch{}
if(priorities[0]===priorities[1])priorities[1]=null;
function preferencesReady(){return priorities.every(Number.isInteger)&&priorities[0]!==priorities[1];}
function allocateRoles(preferences){const result=preferences.map(()=>null),available=new Set(matchRoles.map((_,i)=>i));for(let rank=0;rank<2;rank++)preferences.forEach((pref,i)=>{const choice=pref[rank];if(result[i]===null&&Number.isInteger(choice)&&available.has(choice)){result[i]={role:choice,rank:rank+1,switcher:false};available.delete(choice);}});return result.map(v=>v||{role:null,rank:null,switcher:true});}
function rosterPreferences(){const example=[[0,1],[0,1],[0,1],[3,2],[4,2],[5,4],[3,5],[4,0]].slice(0,classroom.size);if(preferencesReady())example[0]=[...priorities];return example;}
function matchingResult(){const p=rosterPreferences();const ordered=allocateRoles([...p.slice(1),p[0]]);return [ordered[ordered.length-1],...ordered.slice(0,-1)];}
function myAssignment(){return matchingResult()[0];}
function myRoleName(){const a=myAssignment();return a.switcher?'역할 전환자':matchRoles[a.role];}
function selectPriority(rank,role){if(!Number.isInteger(role)||role<0||role>=matchRoles.length)return;const other=1-rank;const old=priorities[rank];if(priorities[other]===role)priorities[other]=old;priorities[rank]=role;state.ready=false;state.roleRevealed=false;persist();try{localStorage.setItem(preferenceKey,JSON.stringify(priorities));}catch{}render();}
function preferencesPanel(){return `<section class="preference-panel teacher-panel"><div class="preference-heading"><div><p class="eyebrow">희망 역할 선택</p><h2>어떤 시선으로 이야기해 볼까요?</h2><p>1순위와 2순위를 골라 주세요. 역할을 끌어 놓거나, 아래 순위 버튼을 눌러 선택할 수 있어요.</p></div><span class="tag subtle">${state.ready?'선택 완료':'두 가지 선택'}</span></div><div class="priority-slots">${[0,1].map(rank=>`<div class="priority-slot" data-priority-slot="${rank}" tabindex="0" role="group" aria-label="${rank+1}순위 선택 영역"><span class="priority-label">${rank+1}순위${rank===0?' · 가장 하고 싶은 역할':' · 다음으로 하고 싶은 역할'}</span>${priorities[rank]===null?'<p class="drop-hint">역할을 여기에 놓아주세요.</p>':`<div class="priority-assigned" draggable="true" data-role-index="${priorities[rank]}">${rolePictogram(matchRoles[priorities[rank]])}<strong>${matchRoles[priorities[rank]]}</strong><button type="button" data-clear-priority="${rank}" aria-label="${rank+1}순위 선택 해제">${icon('close',16)}</button></div>`}</div>`).join('')}</div><div class="preference-roles">${matchRoles.map((role,i)=>`<article class="priority-role" draggable="true" data-role-index="${i}"><div class="priority-role-top">${rolePictogram(role)}<button class="role-drag-handle" type="button" data-role-index="${i}" aria-label="${role} 끌어서 순위에 놓기" title="끌어서 순위에 놓기">⠿</button></div><h3>${role}</h3><p>${roleSymbols[role].meaning}</p><div class="rank-buttons">${[0,1].map(rank=>`<button type="button" data-rank="${rank}" data-pick-role="${i}" aria-label="${role} ${rank+1}순위 선택" aria-pressed="${priorities[rank]===i}">${rank+1}순위${priorities[rank]===i?' ✓':''}</button>`).join('')}</div></article>`).join('')}</div><div class="preference-bottom"><p>1순위 → 2순위 순서로 배정하며, 두 순위 모두 미배정된 학생이 역할 전환자가 돼요.<br><small>동일 순위가 겹치면 입장 순서로 배정해요. 이 시연에서 나는 마지막 입장이고, 역할마다 한 자리예요.</small></p><button class="button" data-match-action="confirm" ${preferencesReady()?'':'disabled'}>희망 역할 선택 완료 ${icon('check',16)}</button></div><span class="sr-only" role="status" aria-live="polite">${priorities.map((r,i)=>`${i+1}순위 ${r===null?'미선택':matchRoles[r]}`).join(', ')}</span></section>`;}
const studentLobby=screens.lobby,studentBriefing=screens.briefing;
screens.lobby=()=>preferencesPanel()+studentLobby();
screens.briefing=()=>studentBriefing().replaceAll('학생회 대표',myRoleName());
roleCard=function(large=false){if(large&&!state.roleRevealed)return `<section class="large-role"><div class="card-back"><div class="role-lock">${icon('lock',27)}</div><p>내 역할 배정 결과</p><span>희망 순위를 우선해서 배정했어요.</span></div></section>`;const a=myAssignment(),role=myRoleName(),symbol=a.switcher?matchRoles[priorities[0]??0]:role;return `<section class="${large?'large-role':'role-mini'}"><div class="panel-heading"><span>나의 역할</span>${!large?`<button data-action="toggle-secret">${state.secretHidden?'보기':'숨기기'}</button>`:''}</div>${!large&&state.secretHidden?'<div class="secret-hidden"><p>역할을 숨겼어요.</p></div>':`<div class="role-content">${rolePictogram(symbol,large?'role-pictogram-large':'role-pictogram-mini')}<h2>${role}</h2><span class="tag">${a.switcher?'희망 역할 미배정':a.rank+'순위 배정'}</span><blockquote>${a.switcher?'희망한 두 역할의 자리가 모두 찼어요.<br>소개하는 역할과 다른 관점으로 토론해요.':roleSymbols[role].meaning}</blockquote>${a.switcher?`<dl class="switcher-perspective"><dt>소개할 역할</dt><dd>${matchRoles[priorities[0]??0]}</dd><dt>토론할 관점</dt><dd>${matchRoles[priorities[1]??1]}</dd></dl>`:''}<div class="role-task-label">토론에서 해볼 일</div><ul class="mission-list"><li>${icon('check',15)}<span>이 입장에서 중요한 점을 이야기해요.</span></li><li>${icon('check',15)}<span>다른 관점의 이유도 물어봐요.</span></li></ul></div>`}</section>`;};
screens.role=()=>{if(!preferencesReady()||!state.ready)return heading('먼저 희망 역할을 골라 주세요.','선택한 순위를 우선해서 역할을 배정해요.')+preferencesPanel();return heading(state.roleRevealed?'나의 역할을 확인해요.':'희망 순위를 반영해 역할을 배정했어요.','두 희망 역할 모두 미배정되면 역할 전환자가 됩니다.')+`<div class="large-role-wrap">${roleCard(true)}<div class="role-explanation"><p class="eyebrow">나의 선택</p><h2>1순위 ${matchRoles[priorities[0]]}<br>2순위 ${matchRoles[priorities[1]]}</h2><p class="section-description">같은 순위의 희망이 겹치면 입장 순서를 적용하는 시연입니다. 다른 참가자의 선택은 예시 데이터예요.</p>${state.roleRevealed?button('생각 정리하기','go-briefing'):button('배정된 역할 확인하기','reveal-role','','eye')}<p class="privacy-line">${icon('lock',13)}배정 결과는 나에게만 보여요.</p></div></div>`;};
function assignmentTable(){const prefs=rosterPreferences(),results=matchingResult();return `<div class="assignment-scroll"><table class="assignment-table"><thead><tr><th>학생 · 입장순</th><th>1순위</th><th>2순위</th><th>배정 결과</th></tr></thead><tbody>${results.map((a,i)=>`<tr><th>${i===0?userName():['','하린','민준','서윤','도윤','지우','수빈','현우'][i]} · ${i===0?classroom.size:i}번째</th><td>${matchRoles[prefs[i][0]]}</td><td>${matchRoles[prefs[i][1]]}</td><td><span class="tag ${a.switcher?'subtle':''}">${a.switcher?'역할 전환자':matchRoles[a.role]+' · '+a.rank+'순위'}</span></td></tr>`).join('')}</tbody></table></div>`;}
screens.result=()=>heading('선택한 순위가 이렇게 배정됐어요.','두 희망 역할 모두 미배정된 참가자가 역할 전환자예요.')+`<section class="teacher-panel"><h2>이 모둠의 역할 배정</h2>${assignmentTable()}<p class="fine">다른 참가자의 희망 순위와 입장 순서는 시연용 예시입니다.</p></section>${button('한 판 돌아보기','go-reflection')}`;
const baseLessonSummary=lessonSummary;
lessonSummary=function(){return baseLessonSummary().replace('<dd>모둠당 '+classroom.swappers+'명</dd>','<dd>희망 미배정 학생 자동</dd>');};
const previousRender=render;
render=function(){const assignments=matchingResult(),prefs=rosterPreferences();assignments.forEach((a,i)=>{if(people[i])people[i].role=a.switcher?matchRoles[prefs[i][0]]:matchRoles[a.role];});previousRender();if(!isTeacher()&&current==='discussion'){const label=$('.voice-speaker p');if(label)label.textContent=voice.active||voice.completed?myRoleName():people[1].role+'로 소개했어요.';}if(isTeacher()){const field=$('.teacher-choice');if(field){const p=field.nextElementSibling;if(p&&p.classList.contains('fine'))p.textContent='역할 전환자는 직접 정하지 않아요. 1·2순위 배정에서 남은 학생이 자동으로 맡아요.';field.remove();}const phase=$('.teacher-panel.observation');if(phase){phase.insertAdjacentHTML('afterend',`<section class="teacher-panel"><div class="teacher-section-title"><h2>${classroom.group}모둠 역할 배정</h2><span class="tag subtle">전환자 ${matchingResult().filter(a=>a.switcher).length}명</span></div>${assignmentTable()}<p class="fine">1순위 우선 → 빈 역할에 2순위 → 미배정 학생은 역할 전환자. 다른 학생의 선택은 예시예요.</p></section>`);}if(location.hash==='#teacher-lobby'){const summary=$('.group-detail');if(summary)summary.insertAdjacentHTML('beforeend','<p class="fine">학생은 1순위·2순위를 고른 뒤 준비해요. 수업 시작 시 희망 순위를 반영해 배정합니다.</p>');}}};
window.addEventListener('click',e=>{const pick=e.target.closest('[data-pick-role]'),clear=e.target.closest('[data-clear-priority]'),confirm=e.target.closest('[data-match-action]');if(pick){e.preventDefault();e.stopImmediatePropagation();selectPriority(Number(pick.dataset.rank),Number(pick.dataset.pickRole));return;}if(clear){e.preventDefault();e.stopImmediatePropagation();priorities[Number(clear.dataset.clearPriority)]=null;state.ready=false;state.roleRevealed=false;persist();try{localStorage.setItem(preferenceKey,JSON.stringify(priorities));}catch{}render();return;}if(confirm){e.preventDefault();e.stopImmediatePropagation();if(!preferencesReady())return;state.ready=true;persist();render();toast('희망 역할을 저장했어요. 순위를 우선해서 배정합니다.');return;}if(e.target.closest('[data-action="ready"]')&&!preferencesReady()){e.preventDefault();e.stopImmediatePropagation();toast('1순위와 2순위를 먼저 선택해 주세요.');$('.preference-panel')?.scrollIntoView({behavior:'smooth',block:'start'});}if(e.target.closest('#reset-demo')){priorities=[null,null];try{localStorage.removeItem(preferenceKey);}catch{}}},true);
let draggedRole=null;
function clearDrag(){document.querySelectorAll('.priority-slot').forEach(el=>el.classList.remove('drag-over'));document.body.classList.remove('role-dragging');}
document.addEventListener('dragstart',e=>{const card=e.target.closest('[draggable="true"][data-role-index]');if(!card)return;draggedRole=Number(card.dataset.roleIndex);e.dataTransfer.setData('text/plain',String(draggedRole));e.dataTransfer.effectAllowed='move';document.body.classList.add('role-dragging');});
document.addEventListener('dragover',e=>{const slot=e.target.closest('[data-priority-slot]');if(!slot||draggedRole===null)return;e.preventDefault();e.dataTransfer.dropEffect='move';clearDrag();slot.classList.add('drag-over');});
document.addEventListener('dragleave',e=>{const slot=e.target.closest('[data-priority-slot]');if(slot&&!slot.contains(e.relatedTarget))slot.classList.remove('drag-over');});
document.addEventListener('drop',e=>{const slot=e.target.closest('[data-priority-slot]');if(!slot||draggedRole===null)return;e.preventDefault();selectPriority(Number(slot.dataset.prioritySlot),draggedRole);draggedRole=null;clearDrag();});document.addEventListener('dragend',()=>{draggedRole=null;clearDrag();});
let touchDrag=null,ghost=null;
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('.role-drag-handle');if(!handle)return;e.preventDefault();handle.setPointerCapture(e.pointerId);touchDrag={pointer:e.pointerId,role:Number(handle.dataset.roleIndex),x:e.clientX,y:e.clientY,active:false};});
document.addEventListener('pointermove',e=>{if(!touchDrag||e.pointerId!==touchDrag.pointer)return;if(!touchDrag.active&&Math.hypot(e.clientX-touchDrag.x,e.clientY-touchDrag.y)<5)return;touchDrag.active=true;if(!ghost){ghost=document.createElement('div');ghost.className='role-drag-ghost';ghost.textContent=matchRoles[touchDrag.role];document.body.append(ghost);}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';clearDrag();document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-priority-slot]')?.classList.add('drag-over');});
function endTouch(e){if(!touchDrag||e.pointerId!==touchDrag.pointer)return;const slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-priority-slot]');if(touchDrag.active&&slot&&e.type!=='pointercancel')selectPriority(Number(slot.dataset.prioritySlot),touchDrag.role);touchDrag=null;ghost?.remove();ghost=null;clearDrag();}document.addEventListener('pointerup',endTouch);document.addEventListener('pointercancel',endTouch);
render();



window.addEventListener('click',e=>{if(e.target.closest('[data-action="opening-starter"]')){e.preventDefault();e.stopImmediatePropagation();const text='저는 '+myRoleName()+'의 입장에서, 모두에게 공정한 기준을 함께 정하고 싶어요.';$('#opening').value=text;state.opening=text;persist();$('#opening').focus();}},true);
